"""Reviewed HTML email sources. Brevo's doubleoptin variable is kept literal."""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parents[1]
LOGO = json.loads((ROOT/'datos/newsletter.json').read_text(encoding='utf-8'))['emailLogo']
OUT = ROOT / '_historial_chat/newsletter-2026-10-24/emails'
OUT.mkdir(parents=True,exist_ok=True)
for en in (False,True):
    lang = 'en' if en else 'es'
    title = 'One click. You are in.' if en else 'Un clic. Y estás dentro.'
    subject = 'Confirm your Lienzo subscription' if en else 'Confirma tu suscripción a Lienzo'
    intro = 'You asked to receive updates from Lienzo. Confirm your email to hear about new tools, free creative resources, and useful improvements in English.' if en else 'Solicitaste recibir novedades de Lienzo. Confirma tu correo para enterarte de nuevas herramientas, recursos gratuitos y mejoras útiles en español.'
    consent = 'I want email updates from Lienzo about tools, resources, and improvements.' if en else 'Quiero recibir por correo las novedades de Lienzo sobre herramientas, recursos y mejoras.'
    ignore = 'Did not request this? Ignore this email. We will not add you to the newsletter unless you confirm.' if en else '¿No lo solicitaste? Ignora este correo. No te añadiremos al boletín si no confirmas.'
    privacy = '/en/privacy/#newsletter' if en else '/privacidad/#boletin'
    html = f'''<!DOCTYPE html><html lang="{lang}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{subject}</title></head><body style="margin:0;background:#f6f4ef;color:#17161f;font-family:Arial,Helvetica,sans-serif"><div style="display:none;max-height:0;overflow:hidden">{subject}. {"New tools and creative resources, without the noise." if en else "Herramientas y recursos creativos, sin ruido."}</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0"><tr><td align="center" style="padding:32px 16px"><table role="presentation" width="600" cellspacing="0" cellpadding="0" style="width:100%;max-width:600px;background:#fffdf9;border:1px solid #e0dde8;border-radius:16px;overflow:hidden"><tr><td style="padding:28px 32px;background:#101018"><a href="https://lienzo.tools/{"en/" if en else ""}"><img src="https://lienzo.tools/assets/email/lienzo-logo.png" width="200" height="54" alt="Lienzo" style="display:block;border:0;color:#ffffff;font-size:28px"></a></td></tr><tr><td style="padding:36px 32px"><p style="font-size:11px;letter-spacing:2px;color:#0d766c;margin:0 0 20px">LIENZO / {"CONFIRM YOUR EMAIL" if en else "CONFIRMA TU CORREO"}</p><h1 style="font-family:Georgia,serif;font-size:36px;line-height:1.15;margin:0 0 24px;font-weight:normal">{title}</h1><p style="font-size:16px;line-height:1.7;color:#5d5c6e;margin:0 0 28px">{intro}</p><p style="margin:0 0 28px"><a href="{{{{ doubleoptin }}}}" style="display:inline-block;background:#5b46e8;color:#ffffff;padding:16px 24px;border-radius:8px;text-decoration:none;font-weight:bold;font-size:16px">{"Confirm my subscription" if en else "Confirmar mi suscripción"}</a></p><p style="font-size:13px;line-height:1.65;color:#5d5c6e;border-top:1px solid #e0dde8;padding-top:20px">{ignore}</p><p style="font-size:12px;line-height:1.6;color:#5d5c6e">{"Your choice" if en else "Tu elección"}: «{consent}»<br>{"Updates have no fixed schedule. You can unsubscribe from each newsletter." if en else "Sin frecuencia fija. Puedes darte de baja desde cada boletín."}</p></td></tr><tr><td style="padding:24px 32px;border-top:1px solid #e0dde8;font-size:12px;line-height:1.7;color:#5d5c6e">Jorge Andrés Arias García · Lienzo<br>Chapinero, Bogotá D.C., Colombia<br><a href="mailto:contacto@lienzo.tools" style="color:#5b46e8">contacto@lienzo.tools</a> · <a href="https://lienzo.tools{privacy}" style="color:#5b46e8">{"Privacy policy" if en else "Política de privacidad"}</a><br><a href="{{{{ unsubscribe }}}}" style="color:#5d5c6e">{"Unsubscribe" if en else "Cancelar suscripción"}</a></td></tr></table></td></tr></table></body></html>'''
    html = html.replace('https://lienzo.tools/assets/email/lienzo-logo.png', LOGO)
    (OUT/f'confirm-{lang}.html').write_text(html,encoding='utf-8')
print('Reviewed ES/EN DOI email HTML written outside public site.')
